function chunkByGap(readings, maxGap) {
  const chunks = [];
  let run = [];
  let prev = null;
  for (const r of readings) {
    if (prev !== null && r.t - prev.t > maxGap) {
      chunks.push(run);
      run.length = 0;
    }
    run.push(r);
    prev = r;
  }
  if (run.length) chunks.push(run);
  return chunks;
}

